 ('mc', 5, 'nafile_tanim', 'Nafile', 'e', '“Nafile namaz” ne demektir?', 'Farz ve vacip dışında, gönüllü olarak kılınan namaz', ['Kılınması yasak olan namaz', 'Yalnızca hacda kılınan namaz', 'Cemaatsiz kılınamayan namaz'], 'Nafile, farz ve vaciplerin dışında Allah rızası için fazladan kılınan namazdır.'),
 ('mc', 5, 'teheccud', 'Teheccüd', 'm', 'Gece bir süre uyuduktan sonra kalkıp kılınan nafile namaza ne denir?', 'Teheccüd', ['Duha', 'Teravih', 'Evvâbîn'], 'İsrâ 17:79’da gecenin bir kısmında teheccüd namazı kılmak tavsiye edilir.'),
 ('mc', 5, 'duha', 'Kuşluk namazı', 'm', 'Güneş yükseldikten öğleye kadar olan vakitte kılınan nafile namaza ne denir?', 'Kuşluk (duha) namazı', ['Teheccüd', 'Vitir', 'İşrak sonrası teravih'], 'Kuşluk (duha) namazı güneşin yükselmesinden öğleye yakın zamana kadar kılınır.'),
 ('mc', 5, 'tahiyyetul_mescid', 'Mescide selam', 'm', 'Camiye girince oturmadan önce kılınan iki rekât nafile namaza ne denir?', 'Tahiyyetü’l-mescid', ['Cenaze namazı', 'Bayram namazı', 'Hacet namazı'], 'Hadis: “Biriniz mescide girince oturmadan önce iki rekât namaz kılsın.” (Buhârî)'),
 ('mc', 5, 'istihare', 'İstihare', 'm', 'Bir işin hayırlısını Allah’tan dilemek için kılınan namaz ve yapılan duaya ne denir?', 'İstihare', ['İstiska', 'Kunut', 'Tesbih'], 'İstihare, iki rekât namazdan sonra okunan duayla Allah’tan hayırlı olanı dilemektir (Buhârî).'),
 ('mc', 5, 'istiska', 'Yağmur duası', 'h', 'Kuraklıkta yağmur için kılınan namaz ve yapılan duaya ne denir?', 'İstiska', ['İstihare', 'Küsûf', 'Tahiyye'], 'İstiska, kuraklık zamanında topluca yağmur için yapılan dua ve namazdır.'),
 ('mc', 5, 'kusuf', 'Güneş tutulması', 'h', 'Güneş tutulduğunda kılınan namaza ne ad verilir?', 'Küsûf namazı', ['Hüsûf namazı', 'Duha namazı', 'Vitir namazı'], 'Güneş tutulmasında küsûf, ay tutulmasında hüsûf namazı kılınır.'),
 ('tf', 5, 'cemaat_27', 'Cemaatin fazileti', 'e', 'Hadise göre cemaatle kılınan namaz, tek başına kılınandan yirmi yedi derece daha faziletlidir.', True, 'Hz. Peygamber: “Cemaatle kılınan namaz tek başına kılınan namazdan yirmi yedi derece üstündür.” (Buhârî, Müslim)'),
 ('tf', 5, 'nafile_ev', 'Evde nafile', 'm', 'Nafile namazların bir kısmını evde kılmak hadislerde teşvik edilmiştir.', True, 'Hz. Peygamber: “Evlerinizde de namaz kılın, onları kabirlere çevirmeyin.” (Buhârî)'),
 ('sc', 5, 'sc_camiye_giris', 'Camiye giriş', 'e', 'Öğle namazından önce camiye erken geldin ve vakit var. Oturmadan önce ne yapabilirsin?', 'Tahiyyetü’l-mescid için iki rekât kılarım', ['Hemen uyurum', 'Telefonla oyun oynarım', 'Cemaati rahatsız ederim'], 'Mescide girince oturmadan iki rekât kılmak sünnettir.'),
 ('sc', 5, 'sc_karar', 'Önemli karar', 'm', 'Zehra iki üniversite arasında karar veremiyor. Dinî açıdan ne yapabilir?', 'Araştırıp danışır, istihare namazı kılıp Allah’tan hayırlısını diler', ['Hiç düşünmeden kura çeker', 'Fal baktırır', 'Kararı tamamen başkasına bırakır'], 'İstihare, araştırma ve danışmayla birlikte Allah’tan hayırlı olanı istemektir; fal ise dinen yasaktır.'),
 ('sc', 5, 'sc_gece', 'Gece ibadeti', 'm', 'Kerem gece ibadetini sevmek istiyor ama sabah namazını kaçırmaktan korkuyor. En dengeli tutum hangisi?', 'Gücü ölçüsünde, yatsıdan sonra veya erken kalkarak kısa bir teheccüd kılmak', ['Hiç uyumamak', 'Sabah namazını feda etmek', 'Gece ibadetini tamamen bırakmak'], 'Nafile ibadette devamlılık ve denge esastır; “Allah’a en sevimli amel az da olsa devamlı olanıdır.” (Buhârî)'),
 ('es', 5, 'es_nafile_farz', 'Nafilenin yeri', 'm', 'Nafile namaz kılan, farz namazı terk etse de olur.', 'Nafileler farzların yerini tutmaz; önce farzlar kılınır', ['Nafile farzdan önemlidir', 'Farzlar yalnızca cuma kılınır', 'Nafile kılan oruç tutmaz'], 'Nafileler farzları tamamlar, onların yerine geçmez.'),
 ('fb', 5, 'fb_tesbih', 'Tesbih namazı', 'h', 'Her rekâtında yetmiş beş, toplamda üç yüz tesbih okunan dört rekâtlık nafileye ___ namazı denir.', 'tesbih', ['cenaze', 'bayram', 'vitir'], 'Tesbih namazında “Sübhânallâhi ve’l-hamdü lillâhi ve lâ ilâhe illallâhu vallâhu ekber” tesbihi toplam üç yüz kez okunur.'),
 ('mi', 5, 'mi_hacet', 'Hacet namazı', 'm', 'Bir ihtiyacın giderilmesi için kılınan nafile namaza ___ namazı denir.', 'hacet', ['vitir', 'cuma', 'bayram'], 'Hacet namazı, bir ihtiyaç için iki rekât kılıp dua etmektir.'),
 ('mt', 5, 'nafile_esle', 'Nafile namazlar', 'm', 'Nafile namazları vakitleriyle eşleştir:', [('Teheccüd', 'Gece uykudan kalkınca'), ('Duha', 'Güneş yükseldikten sonra'), ('Tahiyyetü’l-mescid', 'Camiye girince'), ('Teravih', 'Ramazan gecelerinde')], 'Nafile namazların her birinin kendine özgü bir vakti vardır.'),

 # S6 — Akıllı Tekrar (12)
 ('sr', 6, 'sr_cuma_rekat', 'Cuma', 'e', 'Cumanın farzı kaç rekâttır?', 'İki', ['Dört', 'Üç', 'Bir'], 'Cumanın farzı iki rekâttır.'),
 ('sr', 6, 'sr_cenaze', 'Cenaze', 'e', 'Cenaze namazında kaç tekbir vardır?', 'Dört', ['Üç', 'Beş', 'Altı'], 'Cenaze namazı dört tekbirlidir.'),
 ('sr', 6, 'sr_kasr', 'Yolculuk', 'm', 'Yolcu yatsının farzını kaç rekât kılar?', 'İki', ['Dört', 'Üç', 'Bir'], 'Yolcu dört rekâtlı farzları iki kılar.'),
 ('sr', 6, 'sr_vitir', 'Vitir', 'm', 'Hanefîlere göre vitir kaç rekâttır?', 'Üç', ['Bir', 'İki', 'Beş'], 'Vitir üç rekâttır.'),
 ('tf', 6, 'tf_bayram_hutbe', 'Bayram hutbesi', 'm', 'Bayram hutbesi namazdan önce okunur.', False, 'Bayram hutbesi namazdan sonra, cuma hutbesi ise namazdan önce okunur.'),
 ('tf', 6, 'tf_cenaze_kifaye', 'Cenaze namazı', 'm', 'Cenaze namazı bir kısım Müslümanın kılmasıyla diğerlerinden düşer.', True, 'Cenaze namazı farz-ı kifayedir.'),
 ('tf', 6, 'tf_tahiyye', 'Tahiyyetü’l-mescid', 'e', 'Camiye girince iki rekât namaz kılmak sünnettir.', True, 'Buna tahiyyetü’l-mescid denir.'),
 ('mc', 6, 'mc_tekrar_sehiv', 'Sehiv', 'm', 'Namazda yanılmayı telafi eden secde hangisidir?', 'Sehiv secdesi', ['Tilavet secdesi', 'Şükür secdesi', 'Cenaze secdesi'], 'Sehiv secdesi yanılmaları telafi eder.'),
 ('mc', 6, 'mc_tekrar_istihare', 'İstihare', 'm', 'Hayırlı olanı Allah’tan dilemek için kılınan namaz hangisidir?', 'İstihare', ['İstiska', 'Küsûf', 'Teravih'], 'İstihare, hayırlı olanı dilemek için kılınır.'),
 ('mc', 6, 'mc_tekrar_tesrik', 'Teşrik', 'h', 'Teşrik tekbirleri hangi bayramla ilgilidir?', 'Kurban Bayramı', ['Ramazan Bayramı', 'Hicrî yılbaşı', 'Mevlid'], 'Teşrik tekbirleri arefe ve Kurban Bayramı günlerinde getirilir.'),
 ('es', 6, 'es_tekrar_cuma_kadin', 'Cuma', 'm', 'Cuma namazı kadınlara da erkekler gibi farzdır.', 'Cuma kadınlara farz değildir; kılarlarsa öğle yerine geçer', ['Cuma yalnızca kadınlara farzdır', 'Cuma hiç kimseye farz değildir', 'Kadınlar cuma kılarsa öğleyi de kılar'], 'Cuma erkek, hür, mukim ve sağlıklı Müslümanlara farzdır.'),
 ('es', 6, 'es_tekrar_bayram_ezan', 'Bayram namazı', 'm', 'Bayram namazından önce ezan okunur ve kamet getirilir.', 'Bayram namazında ezan ve kamet yoktur', ['Bayram namazında iki ezan okunur', 'Bayram namazı kametsiz kılınamaz', 'Bayram namazı ezan okunmadan geçersizdir'], 'Bayram namazı ezansız ve kametsiz kılınır.'),

 # S7 — Ünite Challenge (14)
 ('sc', 7, 'ch_yolcu_cuma', 'Yolcu ve cuma', 'h', 'Yolcu olan Hasan cuma günü bir camide cemaatle cuma namazı kıldı. O günün öğle namazı için ne yapar?', 'Cuma öğlenin yerine geçtiği için ayrıca öğle kılmaz', ['Ayrıca dört rekât öğle kılmalıdır', 'Cuma kılması geçersizdir', 'Öğleyi ertesi gün kaza eder'], 'Cuma ile yükümlü olmayan kişi cumayı kılarsa o günün öğle namazı yerine geçer.'),
 ('sc', 7, 'ch_cenaze', 'Cenazeye katılmak', 'm', 'Mahallende bir cenaze namazı kılınacak. Sen de katılıyorsun. Hangisi doğrudur?', 'Dört tekbirle ayakta kılınır, rükû ve secde yapılmaz', ['Rükû ve secdeyle dört rekât kılınır', 'Önce ezan okunur', 'Oturarak kılınması sünnettir'], 'Cenaze namazı ayakta, dört tekbirle kılınır.'),
 ('sc', 7, 'ch_bayram_sabahi', 'Bayram sabahı', 'm', 'Ramazan Bayramı sabahı Yusuf namaza gidecek. Hangisi sünnete uygundur?', 'Gusledip güzel giyinmek ve birkaç hurma yiyerek çıkmak', ['Kahvaltı etmeden aç gitmek şarttır', 'Eski kıyafetle gitmek', 'Namaza gitmeyip kurban kesmek'], 'Ramazan Bayramı’nda namazdan önce hurma yemek, yıkanmak ve güzel giyinmek sünnettir.'),
 ('es', 7, 'ch_es_teravih', 'Teravih', 'm', 'Teravih namazı yılın her gecesinde kılınan bir namazdır.', 'Teravih yalnızca Ramazan gecelerinde kılınır', ['Teravih yalnızca bayram gecesi kılınır', 'Teravih öğle vaktinde kılınır', 'Teravih cuma namazının diğer adıdır'], 'Teravih Ramazan’a özgü bir sünnettir.'),
 ('es', 7, 'ch_es_kasr', 'Kasr', 'h', 'Yolcu akşam namazının farzını iki rekât kılar.', 'Akşam namazının farzı yolculukta da üç rekâttır', ['Yolcu akşamı hiç kılmaz', 'Akşam yolculukta dört rekât olur', 'Akşam yolculukta sabahla birleşir'], 'Kasr yalnızca dört rekâtlı farzlarda uygulanır.'),
 ('pr', 7, 'ch_pr_hutbe', 'Cuma hutbesi', 'm', 'Cuma namazında ___ farzdan önce okunur.', 'hutbe', 'Cuma hutbesi farzdan önce okunur ve cumanın şartıdır.'),
 ('pr', 7, 'ch_pr_kifaye', 'Hüküm', 'm', 'Cenaze namazı farz-ı ___ bir ibadettir.', 'kifaye', 'Bazı Müslümanların kılmasıyla diğerlerinden düşer.'),
 ('pr', 7, 'ch_pr_teheccud', 'Gece namazı', 'm', 'İsrâ 79’da geceleyin kılınması tavsiye edilen nafile namaz ___ namazıdır.', 'teheccüd', 'İsrâ 17:79: “Gecenin bir kısmında da uyanıp sana mahsus bir nafile olarak teheccüd namazı kıl.”'),
 ('mc', 7, 'ch_vacip_hangisi', 'Vacip namazlar', 'h', 'Hanefî mezhebine göre aşağıdakilerden hangisi vacip olan bir namazdır?', 'Vitir namazı', ['Teheccüd namazı', 'Kuşluk namazı', 'Tahiyyetü’l-mescid'], 'Hanefîlere göre vitir ve bayram namazları vaciptir; diğerleri nafiledir.'),
 ('mc', 7, 'ch_farz_kifaye', 'Hüküm', 'm', 'Aşağıdaki namazlardan hangisi farz-ı kifayedir?', 'Cenaze namazı', ['Cuma namazı', 'Sabah namazı', 'Vitir namazı'], 'Cenaze namazı farz-ı kifayedir; cuma ve beş vakit farz-ı ayndır.'),
 ('mt', 7, 'ch_mt_hukum', 'Hükümler', 'h', 'Namazları Hanefî mezhebindeki hükümleriyle eşleştir:', [('Cuma namazı', 'Farz-ı ayn'), ('Cenaze namazı', 'Farz-ı kifaye'), ('Bayram namazı', 'Vacip'), ('Teravih namazı', 'Müekked sünnet')], 'Namazların hükümleri farklıdır.'),
 ('mt', 7, 'ch_mt_rekat', 'Rekâtlar', 'm', 'Namazları rekât sayılarıyla eşleştir:', [('Cumanın farzı', '2 rekât'), ('Vitir (Hanefî)', '3 rekât'), ('Yolcunun öğle farzı', '2 rekât kısaltılmış'), ('Teravih (Hanefî)', '20 rekât')], 'Rekât sayıları namaza göre değişir.'),
 ('sc', 7, 'ch_secde_ayet', 'Secde âyeti', 'h', 'Kur’an okurken bir secde âyetini okudun. Ne yapman gerekir?', 'Tilavet secdesi yaparım', ['Sehiv secdesi yaparım', 'Okumayı bırakırım', 'Kaza namazı kılarım'], 'Secde âyetini okuyan veya duyan kişi tilavet secdesi yapar (Hanefîlere göre vacip).'),
 ('tf', 7, 'ch_tf_cemaat', 'Cemaat', 'm', 'Cemaatle namaz, tek başına kılınan namazdan daha faziletlidir.', True, 'Cemaatle namaz yirmi yedi derece daha faziletlidir (Buhârî, Müslim).'),
